const { options } = cli.parse(["node", "bin", "--base-url", "https://gitlab.com"]);

console.log("options:", options);
console.log("baseUrl:", options.baseUrl);
console.log("b:", options.b);

// Bug: b should NOT be "https://github.com" because --base-url was provided
// The issue says b incorrectly gets the default value
if (options.b === "https://github.com") {
  console.log("BUG CONFIRMED: b incorrectly has default value 'https://github.com'");
  process.exit(1);
} else if (options.b === "https://gitlab.com") {
  console.log("FIXED: b correctly has value 'https://gitlab.com' (same as --base-url)");
  process.exit(0);
} else {
  console.log("b has unexpected value:", options.b);
  process.exit(1);
}

