for (const cliOption of cliOptions) {
  // Check if any name for this option was parsed
  const parsedValue = cliOption.names.find((name) => name in parsed)

  if (parsedValue !== undefined) {
    // Option was parsed: propagate the value to all aliases
    for (const name of cliOption.names) {
      options[name] = parsed[parsedValue]
    }
  } else if (!ignoreDefault && cliOption.config.default !== undefined) {
    // Option was not parsed: set defaults for all aliases
    for (const name of cliOption.names) {
      options[name] = cliOption.config.default
    }
  }

