import { cac } from "./src/index.ts";

console.log("=== Edge Case Tests ===\n");

// Test 1: Parse with short alias -b
console.log("Test 1: Parse with short alias -b");
const cli1 = cac();
cli1.option("-b, --base-url <baseUrl>", "Set the instance URL", {
  default: "https://github.com",
});
const result1 = cli1.parse(["node", "bin", "-b", "https://gitlab.com"]);
console.log("  baseUrl:", result1.options.baseUrl, "=== https://gitlab.com ?", result1.options.baseUrl === "https://gitlab.com");
console.log("  b:", result1.options.b, "=== https://gitlab.com ?", result1.options.b === "https://gitlab.com");
console.assert(result1.options.baseUrl === "https://gitlab.com", "Test 1 failed: baseUrl should be https://gitlab.com");
console.assert(result1.options.b === "https://gitlab.com", "Test 1 failed: b should be https://gitlab.com");

// Test 2: Parse with no options (should use defaults)
console.log("\nTest 2: Parse with no options (should use defaults)");
const cli2 = cac();
cli2.option("-b, --base-url <baseUrl>", "Set the instance URL", {
  default: "https://github.com",
});
const result2 = cli2.parse(["node", "bin"]);
console.log("  baseUrl:", result2.options.baseUrl, "=== https://github.com ?", result2.options.baseUrl === "https://github.com");
console.log("  b:", result2.options.b, "=== https://github.com ?", result2.options.b === "https://github.com");
console.assert(result2.options.baseUrl === "https://github.com", "Test 2 failed: baseUrl should be https://github.com");
console.assert(result2.options.b === "https://github.com", "Test 2 failed: b should be https://github.com");

// Test 3: Boolean flag with aliases
console.log("\nTest 3: Boolean flag with aliases");
const cli3 = cac();
cli3.option("-f, --flag", "A boolean flag");
const result3 = cli3.parse(["node", "bin", "-f"]);
console.log("  flag:", result3.options.flag, "=== true ?", result3.options.flag === true);
console.log("  f:", result3.options.f, "=== true ?", result3.options.f === true);
console.assert(result3.options.flag === true, "Test 3 failed: flag should be true");
console.assert(result3.options.f === true, "Test 3 failed: f should be true");

// Test 4: Multiple options, one parsed one not
console.log("\nTest 4: Multiple options, one parsed one not");
const cli4 = cac();
cli4.option("-a, --alpha <alpha>", "Alpha option", { default: "default-alpha" });
cli4.option("-b, --beta <beta>", "Beta option", { default: "default-beta" });
const result4 = cli4.parse(["node", "bin", "--alpha", "parsed-alpha"]);
console.log("  alpha:", result4.options.alpha, "=== parsed-alpha ?", result4.options.alpha === "parsed-alpha");
console.log("  a:", result4.options.a, "=== parsed-alpha ?", result4.options.a === "parsed-alpha");
console.log("  beta:", result4.options.beta, "=== default-beta ?", result4.options.beta === "default-beta");
console.log("  b:", result4.options.b, "=== default-beta ?", result4.options.b === "default-beta");
console.assert(result4.options.alpha === "parsed-alpha", "Test 4 failed: alpha should be parsed-alpha");
console.assert(result4.options.a === "parsed-alpha", "Test 4 failed: a should be parsed-alpha");
console.assert(result4.options.beta === "default-beta", "Test 4 failed: beta should be default-beta");
console.assert(result4.options.b === "default-beta", "Test 4 failed: b should be default-beta");

// Test 5: No default, parse one alias
console.log("\nTest 5: No default, parse one alias");
const cli5 = cac();
cli5.option("-x, --xray <xray>", "X option");
const result5 = cli5.parse(["node", "bin", "--xray", "value"]);
console.log("  xray:", result5.options.xray, "=== value ?", result5.options.xray === "value");
console.log("  x:", result5.options.x, "=== value ?", result5.options.x === "value");
console.assert(result5.options.xray === "value", "Test 5 failed: xray should be value");
console.assert(result5.options.x === "value", "Test 5 failed: x should be value");

console.log("\n=== All edge case tests passed! ===");

